    private static Nodes.Node[] popNodes(NodeStack stack, int length) {
        if (length == 0) {
            return EMPTY_Node_ARRAY;
        }
        Nodes.Node[] nodes = new Nodes.Node[length];
        for (int i = length - 1; i >= 0; i--) {
            nodes[i] = stack.pop();
        }
        return nodes;
    }

